  { key: "worlds", label: "Worlds", mc: true },
  { key: "commands", label: "Commands", mc: true },
  { key: "history", label: "History", mc: true },
  { key: "schedules", label: "Schedules" },
  { key: "settings", label: "Settings" },
  { key: "activity", label: "Activity" },
];

export function GameServerPanel({
  serverId,
  gameFamily,
  header,
  filesPanel,
  backupsPanel,
  settingsPanel,
  activityPanel,
  initialTab,
}: {
  serverId: string;
  gameFamily: string;
  header: GameHeaderData;
  filesPanel: ReactNode;
  backupsPanel: ReactNode;
  settingsPanel: ReactNode;
  activityPanel: ReactNode;
  initialTab?: string;
}) {
  const isMc = gameFamily === "minecraft";
  const visibleTabs = TABS.filter((t) => !t.mc || isMc);
  const keys = visibleTabs.map((t) => t.key as string);
  const [tab, setTab] = useState<PanelTab>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? (initialTab.toLowerCase() as PanelTab) : "overview"
  );

  const go = (t: PanelTab) => {
    setTab(t);
    window.history.replaceState(null, "", `?tab=${t}`);
    if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <div className="space-y-6">
      <GamePanelHeader serverId={serverId} gameFamily={gameFamily} data={header} />

      <div className="sticky top-2 z-10 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1 backdrop-blur-xl">
        {visibleTabs.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => go(t.key)}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "overview" && <GameOverview serverId={serverId} gameFamily={gameFamily} data={header} onNavigate={go} />}
        {tab === "console" && <GameConsole serverId={serverId} running={header.running} />}
        {tab === "files" && filesPanel}
        {tab === "mods" && <ModStore serverId={serverId} scope="mods" onOpenPlugins={() => go("plugins")} />}
        {tab === "plugins" && <ModStore serverId={serverId} scope="plugins" onOpenPlugins={() => go("mods")} />}
        {tab === "backups" && backupsPanel}
        {tab === "players" && <GamePlayersHub serverId={serverId} running={header.running} playersMax={header.players.max} isMc={isMc} />}
        {tab === "worlds" && isMc && <GameWorlds serverId={serverId} running={header.running} />}
        {tab === "commands" && isMc && <GameCommandLibrary serverId={serverId} running={header.running} />}
        {tab === "history" && isMc && <GamePlayerHistory serverId={serverId} />}
        {tab === "schedules" && <GameSchedules serverId={serverId} />}
        {tab === "settings" && settingsPanel}
        {tab === "activity" && activityPanel}
      </div>
    </div>
  );
}

