export async function listGameOperators(serverId: string): Promise<{ ok: true; operators: string[] } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.family !== "minecraft") return { ok: false, error: "Operators are only available for Minecraft." };
    const limited = throttle(user.id, "mc-mgmt", 30);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) return { ok: true, operators: ["Steve", "Alex"] };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
    const res = await withServerSsh(server as SftpServer, async (conn) => {
      const sshExec = exec;
      const roots = spec.dataRoots.map((r) => `${r}/ops.json`).join(" ");
      const { stdout } = await sshExec(conn, `for f in ${roots}; do [ -f "$f" ] && cat "$f" && exit 0; done; echo "[]"`, 5000);
