// Two tabs, picked via ?tab= so only the active one's data actually gets fetched
// (the Free Minecraft tab does an SSH status round-trip to freemc-host — no reason
// to pay that cost on every games-page view when most people are looking at their
// paid servers). "Free Minecraft" used to be its own sidebar entry; it moved here
// and the sidebar now shows a green "FREE" tag on Game Servers instead (see
// app/dashboard/layout.tsx). /dashboard/free-minecraft itself still works — the
// marketing site and the public server directory deep-link straight to it.
export default async function DashboardGamesPage({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string }>;
}) {
  const { tab } = await searchParams;
  const activeTab = tab === "free" ? "free" : "servers";
  const user = await requireUser();

  return (
    <div className="space-y-6">
      <PortalHero
        variant="games"
        title="Game servers"
        sub="Your ready-to-play game servers — sized and priced per game."
      >
        <DeployButton href="/dashboard/deploy?product=game">Deploy game server</DeployButton>
      </PortalHero>

      <div className="flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1">
        <Link
          href="/dashboard/games"
          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === "servers"
              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
          }`}
        >
          My Servers
        </Link>
        <Link
          href="/dashboard/games?tab=free"
          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === "free"
              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
          }`}
        >
          Free Minecraft
          <span className="ml-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-emerald-300">
            Free
          </span>
        </Link>
      </div>

      {activeTab === "free" ? (
        <FreeMinecraftTabContent />
      ) : (
        <PaidGameServers userId={user.id} />
      )}
    </div>
  );
}

async function PaidGameServers({ userId }: { userId: string }) {
  const servers = await db.server.findMany({
    where: { userId, gamePlanId: { not: null } },
    include: { plan: true, osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "desc" },
  });

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  return (
    <>
      {transitional && <AutoRefresh />}
      {servers.length === 0 ? (
        <EmptyState
          title="No game servers yet"
          sub="Spin up a ready-to-play Minecraft, Rust, Valheim or Palworld server in minutes."
          action={
            <DeployButton href="/dashboard/deploy?product=game">Deploy your first game server</DeployButton>
          }
        />
      ) : (
        <div className="grid gap-3 sm:grid-cols-2">
          {servers.map((s) => {
            const family = s.osTemplate.family;
            const meta = GAME_DISPLAY[family as keyof typeof GAME_DISPLAY] ?? { name: family, glyph: "🎮" };
            return (
              <Link
                key={s.id}
                href={`/dashboard/servers/${s.id}`}
                className="card card-hover block transition"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex min-w-0 items-center gap-3">
                    <span className="text-2xl leading-none" aria-hidden>{meta.glyph}</span>
                    <div className="min-w-0">
                      <p className="truncate font-medium text-slate-100">{s.hostname}</p>
                      <p className="mt-0.5 text-xs text-slate-500">
                        {meta.name}
                        {s.gamePlan ? ` · ${s.gamePlan.name}` : ""}
                        {s.gamePlan?.slots ? ` · ${s.gamePlan.slots} slots` : ""}
                      </p>
                    </div>
                  </div>
                  <StatusDot status={s.status} />
                </div>
                <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
              </Link>
            );
          })}
        </div>
      )}
    </>
  );
}

