export type FreeMcPreset = {
  label: string;
  description: string;
  /** "properties": server.properties toggle only — write+restart on the SAME
   *  container (cheap, fast, what every preset used to be).
   *  "plugins": needs Paper + downloaded plugins baked in at container-creation
   *  time — env vars are immutable on a running container, so this ALWAYS goes
   *  through the same stop->remove->recreate path as a subdomain change (same
   *  data volume, world untouched), just with a different TYPE/plugin env set.
   *  Never silently "restart" a plugins preset — it would do nothing, since
   *  MODRINTH_PROJECTS/SPIGET_RESOURCES are read once at container creation. */
  kind: "properties" | "plugins";
  properties: Record<string, string>;
  /** Only meaningful for kind:"plugins". "PAPER" for every plugin-based preset
   *  here — none of them need Forge/Fabric. */
  type?: "VANILLA" | "PAPER";
  /** Extra env vars for kind:"plugins" (MODRINTH_PROJECTS, SPIGET_RESOURCES,
   *  PLUGINS, ...). Values are shell-quoted individually by the caller. */
  env?: Record<string, string>;
  /** Honest one-line note about what's NOT automated — shown in the UI right
   *  next to the preset. A preset that needs in-game setup says so; nothing
   *  here claims more than the plugin actually does out of the box. */
  setupNote?: string;
  /** Public path (under /public) to an on-brand illustrated hero image for
   *  this mode — see public/games/art/freemc-<mode>_hero.jpg. Only the 8
   *  plugin-based presets have one; the 4 properties-only presets (vanilla/
   *  creative/hardcore/peaceful) intentionally don't, so they stay a plain
   *  text card, same as before this field existed. */
  heroImage?: string;
  /**
   * Short, player-facing command hints for whatever plugin actually drives
   * this game type — shown to the customer via the branded join message (see
   * buildFreemcWelcomeMessage / recreateGameTypeContainer's Essentials patch
   * below). Ordered by importance; the join message only uses the first 3.
   *
   * Every entry here was LIVE-VERIFIED this session by booting a real
   * throwaway container on freemc-host with exactly this type's plugin env
   * and running the command (or `help`) over RCON — not sourced from memory
   * or assumed from a plugin's marketing page, with two exceptions noted per
   * entry below: SkyBlock (verified earlier this same session, before this
   * field existed — not re-verified here) and Towny (root commands confirmed
   * live; the exact `/town new` creation syntax comes from Towny's own
   * official GitHub wiki instead, since RCON's console sender can't exercise
   * a player-only "create a town" command to confirm it first-hand). No
   * entry exists for "vanilla" — it's the one game type with no plugin
   * runtime at all, so there's nothing beyond stock Minecraft commands to
   * hint at.
   */
  helpCommands?: string[];
};

