export type FreeMcGameType = FreeMcPreset & {
  /** Extra plugin-created dimension folder names that do NOT follow the
   *  LEVEL-based naming scheme (see the confirmation note above) — a world
   *  delete must remove these explicitly too, or it leaves orphaned plugin
   *  data behind under a folder name that looks unrelated to the type. */
  extraWorldFolders?: string[];
};

function buildGameType(key: (typeof GAME_TYPE_KEYS)[number]): FreeMcGameType {
  const base = FREEMC_PRESETS[key];
  if (key === "skyblock") {
    return { ...base, extraWorldFolders: ["iridiumskyblock", "iridiumskyblock_nether", "iridiumskyblock_the_end"] };
  }
  return { ...base };
}

/** The 9 GAME TYPES. Deliberately derived from FREEMC_PRESETS rather than
 *  redeclared, so label/description/kind/type/env/setupNote/heroImage can
