/**
 * Translates one of the OLD flat FREEMC_PRESETS keys (still the only thing
 * the not-yet-migrated dashboard UI — components/customer/freemc/*.tsx,
 * components/customer/FreeMinecraftPanel.tsx — ever submits) into the new
 * two-axis (gameType, gameMode) shape. The 3 old mode-only keys collapse onto
 * vanilla+that mode (that's exactly what they always meant); every other key
 * is a game type, always paired with survival (the old flat scheme had no
 * concept of "preserve the current mode across a preset switch" — every
 * preset fully specified its own properties, so this reproduces that
 * behavior exactly rather than inventing a new one for legacy callers).
 * Returns null for anything unrecognized.
 */
function mapLegacyPresetKey(key: string): { gameType: string; gameMode: string } | null {
  if (key === "creative" || key === "hardcore" || key === "peaceful") return { gameType: "vanilla", gameMode: key };
  if (FREEMC_GAME_TYPES[key]) return { gameType: key, gameMode: "survival" };
  return null;
}

/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
 *  not a customer VPS. Reused via the same withServerSsh every game/backup
 *  action already uses; this just points it at our own internal box instead. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

