async function powerAction(action: "start" | "stop" | "restart"): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:power:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      // "start" always wakes a currently-stopped container, and "restart" on
      // one that's ALREADY stopped does too (docker's restart just starts it)
      // — either way that's a customer explicitly turning a container from
      // stopped into running, the exact path lib/freemc-capacity.ts's module
      // doc says this app controls and should gate (unlike mc-router's own
      // passive wake, which happens outside this app entirely). A restart of
      // an already-running container doesn't change what's committed, so it's
      // deliberately left ungated — same reasoning applies to "stop", which
      // only ever frees capacity.
      if (action !== "stop") {
        const running = await exec(
          conn,
          `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`,
          10_000,
        );
        const isRunning = running.code === 0 && running.stdout.trim() === "true";
        if (!isRunning) {
          const assigned = await exec(
            conn,
            `docker inspect ${shellQuote(row.containerName)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`,
            10_000,
          );
          if (assigned.code === 0) {
            const [nanoCpusRaw, memBytesRaw] = assigned.stdout.trim().split(/\s+/);
            const cpus = (Number.parseInt(nanoCpusRaw, 10) || 0) / 1e9;
            const ramMb = Math.round((Number.parseInt(memBytesRaw, 10) || 0) / (1024 * 1024));
            const capacity = await getFreemcHostCapacity(conn);
            const capCheck = wouldExceedFreemcCapacity(capacity, cpus, ramMb);
            if (capCheck.exceeds) {
              return { ok: false as const, error: "Free servers are at capacity right now — try again in a few minutes." };
            }
          }
          // If the inspect itself failed (container missing entirely), fall
          // through and let the docker action below produce the real error —
          // no point capacity-gating a container that doesn't exist.
        }
      }
      const r = await exec(conn, `docker ${action} ${shellQuote(row.containerName)}`, 30_000);
      if (r.code !== 0) return { ok: false as const, error: r.stderr || `docker ${action} failed` };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error(`[free-minecraft] ${action} failed:`, e);
    return { error: "That didn't work — please try again in a moment." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function renameFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
