/**
 * Changes the connect address. The container's own identity (containerName,
 * data volume) never changes — only its `mc-router.host` label does, and
 * labels are immutable on a running container, so this is a stop -> remove ->
 * recreate with the SAME name and data mount, just a new label. World data is
 * untouched throughout; there's a few seconds of downtime while it recreates.
 */
export async function changeFreeMinecraftSubdomain(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };

  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
  const subdomainError = validateSubdomainFormat(sub);
  if (subdomainError) return { error: subdomainError };
  if (sub === row.subdomain) return {};
  if (!(await isSubdomainAvailable(sub, { excludeFreeMcId: row.id }))) return { error: "That name is taken — try another." };

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  // Preserve whatever game type/mode was active — moving your connect
  // address shouldn't reset your world or plugins.
  const gameTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
  const gameType = FREEMC_GAME_TYPES[gameTypeKey];
  const gameMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;

  try {
    await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: sub } });
  } catch {
    return { error: "That name is taken — try another." };
  }

  try {
    const host = await freemcHost();
    // "moved": now running under the new subdomain. "reverted": the new
    // address failed to boot, so it's back under the OLD one — the DB's
    // subdomain field must match, or the dashboard would show a "connect at"
    // address nothing is actually listening on.
    const outcome = await withServerSsh(host, async (conn) => {
      const applied = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: sub,
        domain,
        ramMb,
        ownerId: user.id,
        gameType,
        gameTypeKey,
        gameMode,
      });
      if (applied.ok) return { landed: "moved" as const };
      console.error("[free-minecraft] subdomain recreate failed, rolling back:", applied.error);
      const rolledBack = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: row.subdomain,
        domain,
        ramMb,
        ownerId: user.id,
        gameType,
        gameTypeKey,
        gameMode,
      });
      return rolledBack.ok
        ? { landed: "reverted" as const }
        : { landed: "broken" as const, error: rolledBack.error };
    });

    if (outcome.landed !== "moved") {
      await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: row.subdomain } }).catch(() => {});
    }
    if (outcome.landed === "broken") throw new Error(outcome.error);
    if (outcome.landed === "reverted") {
      return { error: "That address didn't work — your server is back on its previous one." };
    }
  } catch (e) {
    console.error("[free-minecraft] subdomain change failed:", e);
    return { error: "Couldn't move your server to the new address — please try again." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function sendFreeMinecraftCommand(_prev: unknown, formData: FormData): Promise<{ error?: string; response?: string }> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:rcon:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many commands — try again in ${rl.retryAfterSec}s.` };

  const parsed = validateRconCommand(String(formData.get("command") ?? ""));
  if (!parsed.ok) return { error: parsed.error };

  try {
    const host = await freemcHost();
    const result = await withServerSsh(host, (conn) => sendRcon(conn, row.containerName, user.id, parsed.command));
    if (!result.ok) return { error: result.error || "Server is asleep — connect first to wake it up." };
    return { response: result.response };
  } catch (e) {
    console.error("[free-minecraft] rcon command failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
}

