"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { getGameWorlds, sendGameCommand } from "@/lib/actions-game-control";

type WorldEntry = { name: string; sizeBytes: number; isDir: boolean };

function fmt(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

export function GameWorlds({ serverId, running }: { serverId: string; running: boolean }) {
  const [entries, setEntries] = useState<WorldEntry[] | null>(null);
  const [dir, setDir] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const r = await getGameWorlds(serverId);
      if (r.ok) { setEntries(r.entries); setDir(r.dir); setErr(null); }
      else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => { if (running) refresh(); }, [running, refresh]);

  const worlds = entries?.filter((e) => e.isDir && /^world/.test(e.name)) ?? [];
  const totalSize = worlds.reduce((s, e) => s + e.sizeBytes, 0);

  function saveAll() {
    setMsg(null);
    start(async () => {
      const r = await sendGameCommand(serverId, "save-all");
      if (r.ok) setMsg("World saved successfully.");
      else setErr(r.error);
    });
  }

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold">Worlds</h3>
          <p className="mt-0.5 text-sm text-slate-400">
            {dir ? `Located at ${dir}` : "Your server's world directories."}
          </p>
        </div>
        <div className="flex gap-2">
          <button className="btn-ghost text-xs" onClick={saveAll} disabled={pending || !running}>
            {pending ? "Saving…" : "Save all"}
          </button>
          <button className="text-xs text-slate-400 hover:text-white disabled:opacity-40" onClick={refresh} disabled={pending || !running}>
            Refresh
          </button>
        </div>
      </div>

      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
      {msg && <p className="mt-2 text-sm text-emerald-400">{msg}</p>}

      {!running ? (
        <p className="mt-4 text-sm text-slate-500">Start the server to view worlds.</p>
      ) : entries === null ? (
        <p className="mt-4 text-sm text-slate-500">Loading…</p>
      ) : worlds.length === 0 ? (
        <p className="mt-4 text-sm text-slate-500">No world directories found.</p>
      ) : (
        <>
          <ul className="mt-4 divide-y divide-white/[0.06]">
            {worlds.map((w) => (
              <li key={w.name} className="flex items-center justify-between py-3">
                <span className="flex items-center gap-3">
                  <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-500/10 text-lg">
                    {w.name.includes("nether") ? "🔥" : w.name.includes("end") ? "🌌" : "🌍"}
                  </span>
                  <span>
                    <p className="text-sm font-medium text-slate-100">{w.name}</p>
                    <p className="text-xs text-slate-500">{fmt(w.sizeBytes)}</p>
                  </span>
                </span>
              </li>
            ))}
          </ul>
          <div className="mt-3 border-t border-white/[0.06] pt-3">
            <p className="text-xs text-slate-500">Total world size: {fmt(totalSize)}</p>
          </div>
        </>
      )}
    </div>
  );
}
