"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { getServerMods, installMod, uninstallMod, type CatalogMod } from "@/lib/actions-mods";

/**
 * Mod Store — the panel's differentiator. An App-Store-style browse experience
 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
 * version → confirm install flow.
 *
 * REAL backend: catalog + install state + install/uninstall come from
 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
 * (clearly labelled in the UI): star rating, install counts, screenshots,
 * version history, reviews and changelog — the GameMod model has no such fields
 * yet, so they are computed deterministically from the mod's slug so the
 * storefront feels alive. The version dropdown is display-only: the installer
 * always applies the latest compatible build (see the note in the install modal).
 *
 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
 * protection, economy, chat, permissions…), falling back to the full catalog
 * with a note when a family draws no plugin categories.
 */

const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];

// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function ratingFor(m: CatalogMod): number {
  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
}
function installsFor(m: CatalogMod): number {
  const base = 800 + (hash(m.slug) % 90000);
  return m.featured ? base * 4 + 120000 : base;
}
function fmtInstalls(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
  return String(n);
}
function versionsFor(m: CatalogMod): string[] {
  const h = hash(m.slug);
  const major = 1 + (h % 4);
  const minor = h % 12;
  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
}
function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
  const h = hash(m.slug);
  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
  return [
    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
  ];
}

